d=Document(inputs/'JOIV_revised_manuscript.docx')
replace(d,'Abstract—','Abstract—Population representation and network assumptions affect regional accessibility estimates. This study compares modelled coverage across ten interconnected provinces in western Democratic Republic of the Congo using WorldPop 2025, GHS-POP 2025, GHS-SMOD and October 2026 OpenStreetMap data. Complete population grids at one and five kilometres retain rural and unreachable demand. A directed graph preserves mapped geometry and disconnection; maximal covering selects among 26 existing hubs. Experiments comprise 288 factorial optimizations, 108 threshold and repeated-stress runs, and 12 conditional ferry runs. WorldPop estimates 43.30 million inhabitants and GHS-POP 34.03 million, differing by 21.40%. Baseline ten-hub coverage within 100 km is 50.97% and 62.70%. Joint scenarios span 40.40–63.35%, without probabilistic confidence interpretation. Satellite-road length agreement within 100 m is 20.93% with tracks and varies spatially and temporally. A published-route check exposes a large Bandundu detour. Adding only mapped ferry geometry reduces the main-road Kinshasa–Bandundu path from 923 to 399 km, against a 2024 logistics reference of 405 km, conditional on ferry usability. This local structural change leaves optimized five- and ten-hub coverage unchanged and increases fifteen-hub coverage by at most 0.079 percentage points. Conditional spatial resampling and CRITIC-derived criterion weights extend uncertainty and preference diagnostics. These weights represent data contrast and correlations, not expert priorities. Household-access validation, current ferry operations and expert responses remain unverified. Results support a reproducible sensitivity analysis; they establish neither observed mobility nor feasible new-town locations.')
anchor=next(x for x in d.paragraphs if x.text=='III. RESULTS AND DISCUSSION')._p
def method():
 sub(d,'K. Conditional Ferry Connectivity and Data-Derived Weights')
 p(d,'The Logistics Cluster access report of 18 April 2024 identifies Bandundu access via Mongata with a bac and reports 405 km [38]. It also describes difficult road conditions and another ferry-dependent itinerary. Route numbers differ between its table and mapped RN17 annotations; this inconsistency is retained. Three OSM ways forming Bac Bandundu (49809124, 980566897, 980566898) are retrieved on 8 October 2026 [39]. Their geometry is added to each main/track road graph, using exact shared coordinates only. No artificial gap link is created. Bidirectional usability is assumed for a conditional diagnostic; waiting, fares, capacity limits, security and seasonality are omitted. This scenario tests an identifiable structural omission, without certifying current operation or replacing the road-only baseline.')
 p(d,'Twelve new maximal-covering optimizations use this conditional ferry graph: two road-class sets, two population products, and p = 5, 10 and 15. Demand remains the complete one-kilometre grid, connectors remain at most 5 km, and the covering threshold remains 100 km, with no deletion or coordinate displacement. Baselines are matched to the corresponding existing runs. Paths beyond 100 km need not be evaluated for this objective. Each selected-set objective is independently recomputed. These targeted mode-availability tests are distinct from the 288-run factorial and are not fitted failure probabilities.')
 p(d,'A CRITIC-style diagnostic derives weights from the six existing candidate-score columns [40]. Scores retain their common 0–1 transformations rather than being rescaled separately to each grid’s observed extrema. For each strict full-cell environmental screen, sigma_j is score standard deviation across retained centres (ddof = 0), r_jk is Pearson correlation, C_j = sigma_j Σ_k(1 − r_jk), and w_j = C_j / Σ_l C_l. Each retained centre has equal sampling weight. Separate 10- and 25-km computations are compared with the assumed and uniform vectors on exactly the same candidate sets. Tied provincial maxima are retained. Contrast/correlation weights describe the chosen evaluation matrix; they do not estimate expert preferences, validate the six transformations, or justify the original 30/25/20/10/5/10 allocation retrospectively.')
before(d,anchor,method)
anchor=next(x for x in d.paragraphs if x.text=='IV. CONCLUSION')._p
res=pd.read_csv(B/'results/ferry_coverage_results.csv');cw=pd.read_csv(B/'results/critic_weights.csv')
def result():
 sub(d,'K. Ferry Omission and Criterion-Weight Diagnostics')
 p(d,'The original Kinshasa–Bandundu path detours toward Kikwit (Fig. 5). Adding the three mapped ferry ways changes the main-road path from 922.62 to 398.99 km and the track-inclusive path from 879.89 to 384.04 km. The main-road conditional route is 1.48% shorter than the report’s 405-km Mongata itinerary; the track alternative is 5.17% shorter. This explains an important part of the graph discrepancy through a documented omitted mode, conditional on availability. The comparison is a geographically plausible published-route benchmark, not GPS accuracy validation or proof of safe current operation. The 2018 distance of 490 km remains a different, unspecified-itinerary benchmark.')
 fig=d.add_paragraph();fig.alignment=WD_ALIGN_PARAGRAPH.CENTER;fig.paragraph_format.first_line_indent=Mm(0);fig.paragraph_format.keep_with_next=True;fig.add_run().add_picture(str(B/'results/calculated_paths_bandundu.png'),width=Mm(85.4))
 cap=p(d,'Fig. 5. Calculated Kinshasa–Bandundu paths in the road-only graph and after adding mapped Bandundu ferry geometry. Ferry use is assumed, not observed. OSM-derived geometry [19], [39]; plotted in longitude/latitude for diagnosis.');cap.paragraph_format.first_line_indent=Mm(0)
 for r in cap.runs:r.font.size=Pt(8)
 p(d,'All twelve optimizations return solver status zero and zero gap. Coverage for p = 5 and 10 is unchanged within numerical precision; this does not imply identical optimizer-selected sets. For p = 15, the gains are 0.079 and 0.078 percentage points for WorldPop without and with tracks, and 0.050 and 0.049 for GHS-POP (Table XVII). A severe long-distance route discrepancy can therefore coexist with a small change in this specific 100-km covering objective. That result does not establish that omitted ferries elsewhere are unimportant or that population access is validated.')
 rows=[]
 for z in res[res.p==15].itertuples():rows.append(['GHS-POP' if z.product=='GHSPOP' else 'WorldPop','Tracks' if z.tracks else 'Main',f'{z.road_only_baseline_pct:.2f}',f'{z.with_ferry_conditional_pct:.2f}',f'{z.difference_pp:.3f}'])
 table(d,'XVII','Conditional ferry coverage with fifteen hubs',['Product','Road set','Before %','Ferry %','Gain pp'],rows,widths=[23,15,16,16,16.3])
 names={'score_population':'Population','score_road':'Road','score_water':'Water','score_rail':'Rail','score_air':'Air','score_gap':'Territorial gap'}
 rows=[]
 for c in names:rows.append([names[c],f'{100*cw[(cw.grid_km==10)&(cw.criterion==c)].iloc[0].critic_weight:.2f}',f'{100*cw[(cw.grid_km==25)&(cw.criterion==c)].iloc[0].critic_weight:.2f}'])
 table(d,'XVIII','CRITIC-style weights on retained candidate scores',['Criterion','10 km weight %','25 km weight %'],rows,widths=[34,26,26.3])
 p(d,'CRITIC assigns the largest weight to the territorial-gap score: 35.12% at 10 km and 34.09% at 25 km, compared with the assumed 10%. This reflects its dispersion and intercriteria contrast, not measured societal importance. At 10 km, CRITIC changes seven of ten provincial top-centre identities relative to both assumed and uniform weights. At 25 km it changes four of nine relative to assumed weights and three relative to uniform weights. The original allocation is thus not endorsed by this data-derived comparator. Criterion directions, decay scales, candidate sampling and masks remain analyst choices requiring substantive justification. Actual expert responses remain absent, and the main covering objective uses none of these weights.')
before(d,anchor,result)
replace(d,'The audits change interpretation','The audits change interpretation of the earlier application: centralities depend on topology, the specified median elbow is unsupported, and single-candidate provinces explain perfect selection frequencies. Exact solver results establish optimality only within encoded models. External road agreement exposes restricted input representation; the published-route follow-up identifies omitted ferry geometry as a major cause of the Bandundu detour under conditional usability. Twelve additional optimizations show unchanged five- and ten-hub coverage and gains below 0.08 percentage points at fifteen hubs. CRITIC-style weighting supplies an explicit matrix-derived alternative but does not justify normative priorities or replace consultation. Conditional block resampling is not a calibrated total-error distribution. Matched household-access observations, current transport operations and expert responses remain unverified. No historical cause, sovereign economic function or feasible new-town site is demonstrated.')
